using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(b =>
        {
            b.ToContainer("Products");

            // BREAKING CHANGE 1 — Discriminator property renamed
            // EF Core 9 defaults to "$type" instead of "Discriminator".
            // Existing 500K documents use "Discriminator", and direct SQL
            // queries (c.Discriminator) depend on this name. Preserve it.
            b.HasDiscriminator<string>("Discriminator");

            // BREAKING CHANGE 2 — id value format changed
            // EF Core 8 synthesized id as "Product|123".
            // EF Core 9 uses just the raw key value ("123").
            // Existing documents carry the old format; keep it so EF can
            // read them and new writes stay consistent.
            b.HasIdValueGeneration(CosmosIdValueGeneration.EntityTypeAndKey);

            // BREAKING CHANGE 3 — HasIndex now throws for Cosmos
            // EF Core 8 silently ignored HasIndex on the Cosmos provider.
            // EF Core 9 throws InvalidOperationException. Removed.
            // (was: b.HasIndex(p => p.Sku);)
        });
    }
}
class Product { public int Id { get; set; } public string Sku { get; set; } = null!; }

