{
    // BREAKING CHANGE 4 — Synchronous I/O removed for Cosmos provider
    // EF Core 9 throws InvalidOperationException on sync calls like
    // ToList(), First(), Single(), etc. All must be async.
    async Task FindProducts(ProductContext ctx)
    {
        // Direct Cosmos SQL — works because we preserved "Discriminator" above
        var sql = "SELECT * FROM c WHERE c.Discriminator = 'Product' AND c.Sku = @sku";
        var products = await ctx.Products.Where(p => p.Sku == "ABC").ToListAsync();
    }
}

